type ConditionalMiddleware struct {
	Patterns	[]string	// The path patterns to match, e.g., "/api/v1/*"
	Negate		bool		// Apply the middleware to routes matching none of the patterns instead
	Middleware	Middleware	// The middleware function to apply
}

type RateLimitConfig struct {
	Limit	int		// Requests allowed in each Per, e.g. 100
	Per	time.Duration	// The period Limit applies to, e.g. time.Minute
	Burst	int		// Requests allowed at once. Defaults to Limit

	// KeyFunc decides who counts as one client, such as by API key or user ID. Returning ""
	// skips limiting for that request. Defaults to the IP address of the connection.
	KeyFunc	func(*server.Context) string
}

type ValidationConfig struct {
	Validator *validator.Validate	// Optional custom validator. If nil, a new validator is created.
}

methods.doc:
Bind reads the request body and decodes it into dest based on Content-Type.
If binding fails it returns an *HTTPError, ready to pass to c.Error, with a message
that's safe to show to clients. Use ShouldBind for the plain underlying error.

Example:

	if err := c.Bind(&req); err != nil {
		return c.Error(err)
	}

Error turns any error into a response. It tries, in order:
 1. the server's ErrorMapper, set with falcon.WithErrorMapper;
 2. a *ValidationError, which becomes a 422 listing the invalid fields;
 3. an *HTTPError, which becomes a response with its code, message and details;
 4. anything else, which becomes a generic 500. The real error is logged, and
    only sent to the client in debug mode.

Example:

	user, err := repo.Find(id)
	if err != nil {
		return c.Error(err)
	}

Validate runs validation on the target struct using the stored validator,
or the default one if none is set. Invalid fields give a *ValidationError.

Example:

	if err := c.Validate(&req); err != nil {
		return c.Error(err)
	}

