type Context struct {
	Writer	http.ResponseWriter
	Request	*http.Request
	Params	Params
	// Handled means the handler took over the Writer itself (websockets, server-sent
	// events...), so the server must not write anything. Helpers like c.JSON don't set it.
	Handled		bool
